describe("panier", () => {
  it("ajoute un produit", () => {
    cy.visit("/produits/42");
    cy.contains("button", "Ajouter au panier").click();
    cy.get("[data-cy=compteur-panier]").should("have.text", "1");
  });
});

Cypress.Commands.add("connexion", (email, mdp) => {
  cy.session([email], () => {
    cy.visit("/connexion");
    cy.get("[data-cy=email]").type(email);
    cy.get("[data-cy=mdp]").type(mdp, { log: false });
    cy.get("[data-cy=valider]").click();
    cy.url().should("include", "/accueil");
  });
});
